class Solution:
    def constructMaximumBinaryTree(self, nums: list[int]) -> 'TreeNode':
        stack = []
        for value in nums:
            node = TreeNode(value)
            while stack and stack[-1].val < value:
                node.left = stack.pop()
            if stack:
                stack[-1].right = node
            stack.append(node)
        return stack[0] if stack else None
